const o = $('Prep input').first().json.offer;
const clean = s => String(s || '').replace(/\([^)]*\)/g, ' ').replace(/[^\p{L}\p{N}&.+\- ]/gu, ' ').replace(/\s+/g, ' ').trim();
const co = clean(o.company), title = clean(o.job_title);
return [
  { json: { query: (co + ' ' + title + ' interview questions process').slice(0, 300) } },
  { json: { query: (co + ' ' + title + ' interview experience (site:reddit.com OR site:glassdoor.com OR site:teamblind.com)').slice(0, 380) } }
];

const o = $('Prep input').first().json.offer;
const found = [];
const items = $input.all();
for (const it of items) {
  const j = it.json || {};
  for (const grp of [j.web, j.discussions]) {
    const list = grp && grp.results;
    if (list && typeof list.length === 'number') for (let k = 0; k < list.length; k++) {
      const r = list[k];
      if (r && typeof r.url === 'string' && /^https?:\/\//.test(r.url) && typeof r.title === 'string') found.push(r);
    }
  }
}
const strip = s => String(s || '').replace(/<[^>]+>/g, '').replace(/&quot;/g, '"').replace(/&#x27;|&#39;/g, "'").replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const seen = new Set();
const sources = [];
let tooShort = 0;
for (const r of found) {
  const key = r.url.replace(/[?#].*$/, '').replace(/\/$/, '');
  if (seen.has(key)) continue;
  seen.add(key);
  const m = r.url.match(/^https?:\/\/(?:www\.)?([^\/?#:]+)/i);
  const host = m ? m[1].toLowerCase() : '';
  const extra = Array.isArray(r.extra_snippets) ? r.extra_snippets : [];
  const text = strip([r.description].concat(extra).join(' ')).slice(0, 700);
  if (text.length < 40) { tooShort++; continue; }
  const title = strip(r.title).slice(0, 140);
  const general = !/\bintern(ship)?s?\b/i.test(title + ' ' + r.url);
  sources.push({ n: sources.length + 1, title, url: r.url, host, text, general });
  if (sources.length >= 12) break;
}
return [{ json: { company: o.company, job_title: o.job_title, sources, debug: { items: items.length, found: found.length, tooShort } } }];

const src = $('Collect sources').first().json;
const master = $('Prep input').first().json.master || [];
const raw = String($input.first().json.text || '');
const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
let r = {};
if (s >= 0 && e > s) { try { r = JSON.parse(raw.slice(s, e + 1)); } catch (err) {} }
const byN = {}; for (const x of src.sources) byN[x.n] = x;
const byId = {}; for (const m of master) byId[m.id] = m;
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const clip = (t, n) => { t = String(t).trim(); return t.length > n ? t.slice(0, n - 1).trim() + '…' : t; };
const LOGISTICS = /\b(audio|camera|webcam|video software|dress code|attire|internet connection|microphone)\b/i;
const arr = a => (Array.isArray(a) ? a : []);
const clean = a => arr(a).filter(x => x && typeof x.text === 'string' && x.text.trim() && byN[x.source] && !LOGISTICS.test(x.text));
const process = clean(r.process), questions = clean(r.questions), tips = clean(r.tips);
const stories = arr(r.stories).map(x => x && ({
  topic: String(x.topic || '').trim(), why: String(x.why || '').trim(),
  ids: arr(x.ids).filter(id => typeof id === 'string' && byId[id] && /bullet$|^project$|^experience$/.test(byId[id].section))
})).filter(x => x && x.topic && x.ids.length);
const develop = arr(r.develop).filter(x => x && typeof x.area === 'string' && x.area.trim() && typeof x.action === 'string' && x.action.trim());
const nf = arr(r.not_found).filter(x => typeof x === 'string' && x.trim());
const head = 'Interview prep: ' + src.job_title + ' at ' + src.company;

function build(np, nq, nt, nn, ns, nd) {
  const used = new Set();
  const cite = n => (byN[n] ? (used.add(n), ' [' + n + ']' + (byN[n].general ? ' (general role)' : '')) : '');
  const line = x => '- ' + esc(clip(x.text, 200)) + cite(x.source);
  const parts = ['<b>' + esc(head) + '</b>'];
  const P = process.slice(0, np), Q = questions.slice(0, nq), T = tips.slice(0, nt), N = nf.slice(0, nn), S = stories.slice(0, ns), D = develop.slice(0, nd);
  if (P.length) parts.push('<b>Process</b>\n' + P.map(line).join('\n'));
  if (Q.length) parts.push('<b>Questions reported</b>\n' + Q.map(line).join('\n'));
  if (S.length) parts.push('<b>Your stories to tell</b>\n' + S.map(x => '- ' + esc(clip(x.topic, 90)) + ': ' + x.ids.slice(0, 2).map(id => esc(clip(byId[id].text, 110))).join(' / ') + (x.why ? '\n   ' + esc(clip(x.why, 160)) : '')).join('\n'));
  if (D.length) parts.push('<b>Areas to develop</b>\n' + D.map(x => '- ' + esc(clip(x.area, 80)) + ': ' + esc(clip(x.action, 180)) + cite(Number(x.source))).join('\n'));
  if (T.length) parts.push('<b>Tips</b>\n' + T.map(line).join('\n'));
  if (N.length) parts.push('<b>Not found</b>\n' + N.map(x => '- ' + esc(clip(x, 160))).join('\n'));
  parts.push('<b>Sources</b>\n' + [...used].sort((a, b) => a - b).map(n => '[' + n + '] <a href="' + esc(byN[n].url).replace(/"/g, '&quot;') + '">' + esc(clip(byN[n].title, 80)) + '</a>').join('\n'));
  parts.push('<i>Sources are public web excerpts, not verified. Stories come from your master CV; development actions are suggestions.</i>');
  return parts.join('\n\n');
}

let out;
if (src.sources.length < 2 || (process.length + questions.length + tips.length) < 2) {
  out = esc(head + '\n\nI could not find enough reliable interview feedback for this role online, so I prefer not to guess. Look at Glassdoor, Blind or the company careers page, and ask people who did this internship.');
} else {
  const tries = [[5, 6, 4, 2, 3, 4], [4, 5, 4, 2, 3, 4], [4, 4, 3, 1, 3, 3], [3, 4, 3, 1, 3, 3], [3, 3, 2, 1, 2, 3], [3, 3, 2, 0, 2, 2], [2, 2, 1, 0, 2, 2]];
  for (const t of tries) { out = build(...t); if (out.length <= 3800) break; }
  if (out.length > 3900) out = out.slice(0, 3800);
}
return [{ json: { text: out } }];
